/// Test-owned output file generated by the compiler and removed after module unloading.
struct Artifact final : SourceArtifact {
    explicit Artifact(std::string path) : path(std::move(path)) {}
    ~Artifact() override { std::remove(path.c_str()); }
    std::string path;
};

/// Test-owned loaded module, held until the source procedure has returned.
struct Module final : LoadedSourceProcedure {
    Module(void* library, const NativeProcedureDescriptor* descriptor) : library(library), value(descriptor) {}
    ~Module() override { if (library) dlclose(library); }
    const NativeProcedureDescriptor* descriptor() const noexcept override { return value; }
    void* library;
    const NativeProcedureDescriptor* value;
};

/// A native host adapter compiles source through stdin without a shell, then loads the artifact.
class Compiler final : public SourceProcedureBackend {
public:
    Compiler(std::string compiler, std::string output, std::string library, std::string root, std::string build)
        : compiler_(std::move(compiler)), output_(std::move(output)), library_(std::move(library)),
          root_(std::move(root)), build_(std::move(build)) {}
    SourceCompilation compile(std::string_view, std::string_view source) override {
        ++compilations;
        int pipes[2];
        if (pipe(pipes) != 0) return {Status::handler_failed, "pipe failed", {}};
        posix_spawn_file_actions_t actions;
        posix_spawn_file_actions_init(&actions);
        posix_spawn_file_actions_adddup2(&actions, pipes[0], STDIN_FILENO);
        posix_spawn_file_actions_addclose(&actions, pipes[1]);
        std::vector<std::string> arguments{compiler_, "-std=c++23", "-shared", "-fPIC",
            "-I" + root_ + "/src", "-I" + root_ + "/src/ModuleImports", "-I" + build_ + "/public",
            "-I" + root_ + "/resources/native_procedure", "-x", "c++", "-", "-x", "none",
            library_, "-Wl,-rpath," + build_, "-o", output_};
        std::vector<char*> argv;
        for (auto& argument : arguments) argv.push_back(argument.data());
        argv.push_back(nullptr);
        pid_t pid{};
        const int spawned = posix_spawnp(&pid, compiler_.c_str(), &actions, nullptr, argv.data(), environ);
        posix_spawn_file_actions_destroy(&actions);
        close(pipes[0]);
        if (spawned != 0) { close(pipes[1]); return {Status::handler_failed, "spawn failed", {}}; }
        std::size_t position = 0;
        while (position < source.size()) {
            const auto count = write(pipes[1], source.data() + position, source.size() - position);
            if (count < 0 && errno == EINTR) continue;
            if (count <= 0) break;
            position += static_cast<std::size_t>(count);
        }
        close(pipes[1]);
        int status = 0;
        pid_t waited;
        do { waited = waitpid(pid, &status, 0); } while (waited < 0 && errno == EINTR);
        if (waited != pid || position != source.size() || !WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            std::remove(output_.c_str());
            return {Status::handler_failed, "compilation failed", {}};
        }
        return {Status::ok, "", std::make_unique<Artifact>(output_)};
    }
    SourceLoad load(const SourceArtifact& artifact) override {
        ++loads;
        const auto& file = static_cast<const Artifact&>(artifact);
        void* library = dlopen(file.path.c_str(), RTLD_NOW | RTLD_LOCAL);
        if (!library) return {Status::handler_failed, dlerror(), {}};
        const auto provider = reinterpret_cast<NativeProcedureDescriptorEntry>(
            dlsym(library, native_procedure_entry_symbol.data()));
        const auto* descriptor = provider ? provider() : nullptr;
        if (!descriptor) {
            dlclose(library);
            return {Status::handler_failed, "missing procedure descriptor", {}};
        }
        return {Status::ok, "", std::make_unique<Module>(library, descriptor)};
    }
    int compilations = 0;
    int loads = 0;
private:
    std::string compiler_, output_, library_, root_, build_;
};

/// Compile a source string at runtime, run it against a tracked app object, then release both.
int main(int argc, char** argv) {
    assert(argc == 7);
    std::ifstream file(argv[2]);
    const std::string source{std::istreambuf_iterator<char>(file), std::istreambuf_iterator<char>()};
    assert(!source.empty());
    Compiler compiler(argv[1], argv[3], argv[4], argv[5], std::string(argv[5]) + "/build");
    Runtime runtime([](const AccessRequest& request) { return request.context.principal == "agent"; });
    auto app = runtime.make_tracked_object<native_procedure_fixture::Application>(
        {"application", "Application", "", "Draft"});
    assert(app.status == Status::ok);
    assert(runtime.add_capability({"application", "publish-title", "", "", "", {}},
        [](std::string_view, std::string&) { return true; },
        [&](const AgentContext&, std::string_view value) {
            return Result{runtime.update_state("application", std::string(value)), std::string(value)};
        }) == Status::ok);
    const auto result = runtime.execute_source({"agent"}, "agent.authored", source, compiler, "Live title");
    assert(result.status == Status::ok && result.value == "Live title" && app.object->title() == "Live title");
    assert(runtime.object({"agent"}, "application")->state == "Live title");
    assert(access(argv[3], F_OK) != 0);

    // The agent discovers the runtime contract and supplies only its own C++ body.
    const auto authoring = runtime.procedure_authoring_context({"agent"});
    const auto found = std::find_if(authoring.objects.begin(), authoring.objects.end(),
        [](const auto& item) { return item.object.id == "application"; });
    assert(found != authoring.objects.end() && found->native_writable);
    assert(found->capabilities.size() == 1 && found->capabilities.front().id == "publish-title");
    std::ifstream body_file(argv[6]);
    const std::string body{std::istreambuf_iterator<char>(body_file), std::istreambuf_iterator<char>()};
    assert(!body.empty());
    const ProcedureDraft draft{"agent.\"\\\n한글", "#include \"Application.h\"", body};
    auto built = runtime.build_procedure({"agent"}, draft, compiler);
    assert(built.status == Status::ok && built.procedure && compiler.compilations == 2);
    assert(access(argv[3], F_OK) == 0);
    assert(runtime.execute_built({"agent"}, *built.procedure, compiler, "Authored first").value == "Authored first");
    assert(runtime.execute_built({"agent"}, *built.procedure, compiler, "Authored second").value == "Authored second");
    assert(compiler.compilations == 2 && compiler.loads == 3);
    assert(app.object->title() == "Authored second");
    assert(runtime.object({"agent"}, "application")->state == "Authored second");
    built.procedure.reset();
    assert(access(argv[3], F_OK) != 0);
    app.object.reset();
    assert(!runtime.object({"agent"}, "application"));
}
